(326057, 25007, 4159, '<td valign="top">I think this picture suffers from oversharpening...something makes it look a bit unreal.  Good catch, though, and nice composition.</td>', 'I think this picture suffers from oversharpening...something makes it look a bit unreal.  Good catch, though, and nice composition.', '2003-06-16 01:48:10.000000', NULL, 1),
(326058, 25018, 4159, '<td valign="top">Weird light on a carpet?  Not sure I understand the subject, but the colors are pleasant.</td>', 'Weird light on a carpet?  Not sure I understand the subject, but the colors are pleasant.', '2003-06-16 01:48:50.000000', NULL, 1),
(326059, 24728, 7242, '<td valign="top">Beautiful shot! I love the tones and mood of this. 10</td>', 'Beautiful shot! I love the tones and mood of this. 10', '2003-06-16 01:49:18.000000', NULL, 1),
(326062, 24592, 4159, '<td valign="top">The light cast by this lamplight appears too white, almost alien.  Generally a night scene is communicated better with more muted lighting - this is harsh.</td>', 'The light cast by this lamplight appears too white, almost alien.  Generally a night scene is communicated better with more muted lighting - this is harsh.', '2003-06-16 01:50:21.000000', NULL, 1),
(326068, 24948, 4159, '<td valign="top">Definitely a solitary feel to this picture.  Something unreal about the colors, though - did you saturate the green?</td>', 'Definitely a solitary feel to this picture.  Something unreal about the colors, though - did you saturate the green?', '2003-06-16 01:56:07.000000', NULL, 1),
