(326242, 24915, 8522, '<td valign="top">Great expression, well captured! 10</td>', 'Great expression, well captured! 10', '2003-06-16 05:40:19.000000', NULL, 1),
(326243, 24378, 6349, '<td valign="top">I have no idea what this is, but its pretty cool art.  I dont like the border though.</td>', 'I have no idea what this is, but its pretty cool art.  I dont like the border though.', '2003-06-16 05:40:35.000000', NULL, 1),
