INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(326274, 24792, 8522, '<td valign="top">Wonderful picture. I love that grain effect on your subject. Great colours. This would have got a 10 without that hideous border! 9</td>', 'Wonderful picture. I love that grain effect on your subject. Great colours. This would have got a 10 without that hideous border! 9', '2003-06-16 05:58:41.000000', NULL, 1),
(326275, 24958, 6349, '<td valign="top">what?!  Is that a real building?  Crazy!  I like it.</td>', 'what?!  Is that a real building?  Crazy!  I like it.', '2003-06-16 05:58:55.000000', NULL, 1),
(326276, 24993, 6349, '<td valign="top">What''s the present?  The kid or the swingset?</td>', 'What''s the present?  The kid or the swingset?', '2003-06-16 05:59:37.000000', NULL, 1),
(326277, 24829, 8522, '<td valign="top">Incredible lighting. Great colours. Love the cloud. Some great textures in there. 9</td>', 'Incredible lighting. Great colours. Love the cloud. Some great textures in there. 9', '2003-06-16 05:59:39.000000', NULL, 1),
(326279, 24840, 6349, '<td valign="top">wierd.  i took almost the same picture 2 days ago.  I will say the same thing about this that i did about my own.  I should have gotten closer to the bug, but the colors are wonderful.</td>', 'wierd.  i took almost the same picture 2 days ago.  I will say the same thing about this that i did about my own.  I should have gotten closer to the bug, but the colors are wonderful.', '2003-06-16 06:00:54.000000', NULL, 1),
(326281, 24931, 6349, '<td valign="top">Very crisp.  How do you get such a clean sharp shot?  Is it just your camera?  I''d really like to know.</td>', 'Very crisp.  How do you get such a clean sharp shot?  Is it just your camera?  I''d really like to know.', '2003-06-16 06:01:58.000000', NULL, 1),
(326282, 24455, 8522, '<td valign="top">Lovely shot, I would have played around with the levels a little more to get the darker shades darker, possibly adjusted the gamma as well so that it doesn''t appear quite so washed out (only a little). I love those feet!  You captured all the character in this bird. Nicely blurred background. 9</td>', 'Lovely shot, I would have played around with the levels a little more to get the darker shades darker, possibly adjusted the gamma as well so that it doesn''t appear quite so washed out (only a little). I love those feet!  You captured all the character in this bird. Nicely blurred background. 9', '2003-06-16 06:02:21.000000', NULL, 1),
(326284, 24918, 6349, '<td valign="top">great portrait.  i would have cropped off the left.</td>', 'great portrait.  i would have cropped off the left.', '2003-06-16 06:04:49.000000', NULL, 1),
(326285, 24932, 6349, '<td valign="top">well hello to you too tucan sam.  my what pretty colors you have.  i like the motion like blur in the background too, is that from wind?</td>', 'well hello to you too tucan sam.  my what pretty colors you have.  i like the motion like blur in the background too, is that from wind?', '2003-06-16 06:05:31.000000', NULL, 1),
