(326288, 24914, 6349, '<td valign="top">cool diagonal composition.</td>', 'cool diagonal composition.', '2003-06-16 06:07:15.000000', NULL, 1),
(326289, 25016, 6349, '<td valign="top">i like this a lot.  im sure you wont score well and people will think the lack of focus is a mistake not understanding your artistic vision.  keep doing what you''re doing.</td>', 'i like this a lot.  im sure you wont score well and people will think the lack of focus is a mistake not understanding your artistic vision.  keep doing what you''re doing.', '2003-06-16 06:09:00.000000', NULL, 1),
(326290, 24606, 6349, '<td valign="top">great shot.  love the lines and the choice of black and white.</td>', 'great shot.  love the lines and the choice of black and white.', '2003-06-16 06:10:47.000000', NULL, 1),
