(331048, 24736, 8637, '<td valign="top">Beautiful shot...if I had a critique it might be to see a little more of the child, at least some hair of the head.  But super photo.  thanks</td>', 'Beautiful shot...if I had a critique it might be to see a little more of the child, at least some hair of the head.  But super photo.  thanks', '2003-06-19 09:31:37.000000', NULL, 1),
(331054, 24592, 8637, '<td valign="top">The person is a little fuzzy but overall I really like thyis shot.  Gave it a 9 and thanks!</td>', 'The person is a little fuzzy but overall I really like thyis shot.  Gave it a 9 and thanks!', '2003-06-19 09:36:09.000000', NULL, 1),
(331106, 24910, 9373, '<td valign="top">Beautiful DOF and very crisp, well focused shot.<br/>Nice choice of a somewhat unique subject. Not many people can find the beauty in a slug!<br/></td>', 'Beautiful DOF and very crisp, well focused shot.Nice choice of a somewhat unique subject. Not many people can find the beauty in a slug!', '2003-06-19 10:53:07.000000', NULL, 1),
(331110, 24735, 9373, '<td valign="top">Pretty good stop action on this obviously fast moving subject. However, someone poked his head into this shot, which detracts from the picture. I can see that you wanted to use the dirt hill as a reference point, but the half cropped face is really distracting.</td>', 'Pretty good stop action on this obviously fast moving subject. However, someone poked his head into this shot, which detracts from the picture. I can see that you wanted to use the dirt hill as a reference point, but the half cropped face is really distracting.', '2003-06-19 10:59:33.000000', NULL, 1),
(331152, 24634, 9373, '<td valign="top">Very good idea that probably didn''t result in exactly what you were thinking. Too soft for my liking.</td>', 'Very good idea that probably didn''t result in exactly what you were thinking. Too soft for my liking.', '2003-06-19 11:47:21.000000', NULL, 1),
(331199, 24359, 6900, '<td valign="top">Just a bit too much negative space.</td>', 'Just a bit too much negative space.', '2003-06-19 12:16:08.000000', NULL, 1),
(331201, 24992, 6900, '<td valign="top">Nice coloring, perhaps a bit less red, more yellow would look even better.</td>', 'Nice coloring, perhaps a bit less red, more yellow would look even better.', '2003-06-19 12:16:43.000000', NULL, 1),
(331209, 24913, 6900, '<td valign="top">This would have ribboned in Matrix, when people were thinking about it.  I LOVE the way the spoon disappears into the background.  If I had the creativity to think of this shot, I would have shot this same thing.  Excellent shot.</td>', 'This would have ribboned in Matrix, when people were thinking about it.  I LOVE the way the spoon disappears into the background.  If I had the creativity to think of this shot, I would have shot this same thing.  Excellent shot.', '2003-06-19 12:21:47.000000', NULL, 1),
(331213, 24516, 6900, '<td valign="top">Fine work with silhouettes.  Looks like Sonifo''s work (a compliment if this isn''t hers).  I think there''s a touch too much neg space at the top.  Great shot.  9</td>', 'Fine work with silhouettes.  Looks like Sonifo''s work (a compliment if this isn''t hers).  I think there''s a touch too much neg space at the top.  Great shot.  9', '2003-06-19 12:25:16.000000', NULL, 1),
(331216, 24792, 6900, '<td valign="top">Really strange border color.  Doesn''t help the shot.</td>', 'Really strange border color.  Doesn''t help the shot.', '2003-06-19 12:27:15.000000', NULL, 1),
(331256, 24675, 8610, '<td valign="top">Like this one, Straight to the point. 9</td>', 'Like this one, Straight to the point. 9', '2003-06-19 12:58:40.000000', NULL, 1),
(331263, 24996, 8610, '<td valign="top">Good idea, fine shadows. Thumbs up for this one. 9</td>', 'Good idea, fine shadows. Thumbs up for this one. 9', '2003-06-19 13:03:43.000000', NULL, 1),
(331267, 24963, 8610, '<td valign="top">Like it... where is this taken?</td>', 'Like it... where is this taken?', '2003-06-19 13:04:11.000000', NULL, 1),
(331296, 24606, 9262, '<td valign="top">I really like the way the steps curve around this shot and how you have captured your subject in mid jump.</td>', 'I really like the way the steps curve around this shot and how you have captured your subject in mid jump.', '2003-06-19 13:26:59.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(331301, 24915, 9262, '<td valign="top">I like the crop on this shot and the emotion showing on your subjects face.</td>', 'I like the crop on this shot and the emotion showing on your subjects face.', '2003-06-19 13:28:56.000000', NULL, 1),
(331306, 24948, 9262, '<td valign="top">I really love this shot. It doesn''t look very real, but I think that''s what I like best. The only thing I would say is that I would like the leaves to be a different shade of green, but I think that is against editing rules :)</td>', 'I really love this shot. It doesn''t look very real, but I think that''s what I like best. The only thing I would say is that I would like the leaves to be a different shade of green, but I think that is against editing rules :)', '2003-06-19 13:31:43.000000', NULL, 1),
(331309, 24890, 9262, '<td valign="top">I love the stark white of the church. It draws your eye to the subject of the shot.</td>', 'I love the stark white of the church. It draws your eye to the subject of the shot.', '2003-06-19 13:32:55.000000', NULL, 1),
(331315, 24559, 9262, '<td valign="top">I like how you have added a second flower at a lower height. I think most people would have just done the stalk with the caterpillar.</td>', 'I like how you have added a second flower at a lower height. I think most people would have just done the stalk with the caterpillar.', '2003-06-19 13:34:30.000000', NULL, 1),
(331316, 24823, 9262, '<td valign="top">I like the stong lines and lighting in this shot.</td>', 'I like the stong lines and lighting in this shot.', '2003-06-19 13:35:08.000000', NULL, 1),
(331318, 24636, 9262, '<td valign="top">This is a very simple, yet effective shot. The negative space really emphasizes your subject. Well done :)</td>', 'This is a very simple, yet effective shot. The negative space really emphasizes your subject. Well done :)', '2003-06-19 13:36:29.000000', NULL, 1),
(331322, 24954, 9262, '<td valign="top">My favoritte thing about this shot is all the dings and scratches on the coin.  The curve down through the composition is very effective as well :)</td>', 'My favoritte thing about this shot is all the dings and scratches on the coin.  The curve down through the composition is very effective as well :)', '2003-06-19 13:38:35.000000', NULL, 1),
(331338, 24925, 9262, '<td valign="top">It took me a bit to figure out what this was. I think including more of the bottom of the stairwell would make this a better shot.</td>', 'It took me a bit to figure out what this was. I think including more of the bottom of the stairwell would make this a better shot.', '2003-06-19 13:45:49.000000', NULL, 1),
(331339, 25016, 9262, '<td valign="top">Concept is good, but more focus would be better :)</td>', 'Concept is good, but more focus would be better :)', '2003-06-19 13:47:16.000000', NULL, 1),
(331347, 24634, 9262, '<td valign="top">I don''t really see how the smoke/dry ice fits in with this image. It is obscuring most of your subject and the background that is visible isn''t very appealing.</td>', 'I don''t really see how the smoke/dry ice fits in with this image. It is obscuring most of your subject and the background that is visible isn''t very appealing.', '2003-06-19 13:50:43.000000', NULL, 1),
(331351, 24469, 9262, '<td valign="top">I like the symmetry of the windows but the perspective of this shot throws me off.</td>', 'I like the symmetry of the windows but the perspective of this shot throws me off.', '2003-06-19 13:52:33.000000', NULL, 1),
(331354, 24741, 9262, '<td valign="top">I think there is too much negative space in this shot that does little to emphasize your subject which is bright enough without all the contrast.</td>', 'I think there is too much negative space in this shot that does little to emphasize your subject which is bright enough without all the contrast.', '2003-06-19 13:53:24.000000', NULL, 1),
(331357, 25015, 1041, '<td valign="top">Nice capture and good fit for the challenge.  I like all the crisscross lines in the photo.  The lighting''s a bit harsh though, it looks like you took this during the day in full sun.  Maybe an early morning or late afternoon photo would have some softer lighting (the golden hours).</td>', 'Nice capture and good fit for the challenge.  I like all the crisscross lines in the photo.  The lighting''s a bit harsh though, it looks like you took this during the day in full sun.  Maybe an early morning or late afternoon photo would have some softer lighting (the golden hours).', '2003-06-19 13:55:21.000000', NULL, 1),
(331361, 24917, 9262, '<td valign="top">This shot looks like you laid some green construction paper on the carpet/floor and then took a picture of your subject. I think it would be better if you put the construction paper against the wall. Yes, your subject is off center which fits the challenge. I do like some of the reflections in the base of the glass but the red against the green just reminds me of Christmas and that seeems out of context of your shot.</td>', 'This shot looks like you laid some green construction paper on the carpet/floor and then took a picture of your subject. I think it would be better if you put the construction paper against the wall. Yes, your subject is off center which fits the challenge. I do like some of the reflections in the base of the glass but the red against the green just reminds me of Christmas and that seeems out of context of your shot.', '2003-06-19 13:58:45.000000', NULL, 1),
(331366, 25017, 9262, '<td valign="top">Ok, you titled your shot "Church at Night" but there is very little of it in your composition. The colors in the sky are nice, but I think a tighter focus on the churc and much less foreground would make this a better shot.</td>', 'Ok, you titled your shot "Church at Night" but there is very little of it in your composition. The colors in the sky are nice, but I think a tighter focus on the churc and much less foreground would make this a better shot.', '2003-06-19 14:02:15.000000', NULL, 1),
(331372, 24745, 9262, '<td valign="top">I think this shot is too blurry and the background is too cluttered.</td>', 'I think this shot is too blurry and the background is too cluttered.', '2003-06-19 14:04:40.000000', NULL, 1),
(331395, 24985, 9262, '<td valign="top">I really like the tilted perspective of this shot.</td>', 'I really like the tilted perspective of this shot.', '2003-06-19 14:18:37.000000', NULL, 1),
(331433, 24950, 6597, '<td valign="top">I like the way the countryside shows through the Hole in the wall. make for a very interesting photo.</td>', 'I like the way the countryside shows through the Hole in the wall. make for a very interesting photo.', '2003-06-19 15:16:48.000000', NULL, 1),
(331436, 24735, 6597, '<td valign="top">great action shot but would have been better without part of someone''s heat I would have cropped that out            6</td>', 'great action shot but would have been better without part of someone''s heat I would have cropped that out            6', '2003-06-19 15:19:21.000000', NULL, 1),
(331455, 24636, 9501, '<td valign="top">can I get a copy to hang on my wall?</td>', 'can I get a copy to hang on my wall?', '2003-06-19 15:38:45.000000', NULL, 1),
(331471, 24857, 2983, '<td valign="top">Very nice work with the off-center focus point that leads the eye to the rest of the frame.</td>', 'Very nice work with the off-center focus point that leads the eye to the rest of the frame.', '2003-06-19 15:48:11.000000', NULL, 1),
(331533, 24969, 5112, '<td valign="top">Very, very beautiful!  Where is this?  I''m trying to make out the flag, and it almost looks blue/white/blue.  Love the rocks in the front.  ~10</td>', 'Very, very beautiful!  Where is this?  I''m trying to make out the flag, and it almost looks blue/white/blue.  Love the rocks in the front.  ~10', '2003-06-19 16:23:59.000000', NULL, 1),
(331535, 24728, 5112, '<td valign="top">I''m not sure why I like this picture, but I really do.  One of my two 10s this week.</td>', 'I''m not sure why I like this picture, but I really do.  One of my two 10s this week.', '2003-06-19 16:24:34.000000', NULL, 1),
(331536, 24950, 5112, '<td valign="top">Very nice.  I like the focus.  The pink flowers are a nice touch.  ~9</td>', 'Very nice.  I like the focus.  The pink flowers are a nice touch.  ~9', '2003-06-19 16:25:11.000000', NULL, 1),
(331539, 24913, 5112, '<td valign="top">Beautiful.  I love how the spoon gets lost into the white background.  ~9</td>', 'Beautiful.  I love how the spoon gets lost into the white background.  ~9', '2003-06-19 16:25:44.000000', NULL, 1),
(331544, 24962, 5112, '<td valign="top">I like the graininess in this picture, and the contrast between the indigo grey skies and the golden cupula.  ~9</td>', 'I like the graininess in this picture, and the contrast between the indigo grey skies and the golden cupula.  ~9', '2003-06-19 16:29:22.000000', NULL, 1),
(331546, 24677, 5112, '<td valign="top">Very interesting!  Excellent entry for the challenge.  The border is beautiful.</td>', 'Very interesting!  Excellent entry for the challenge.  The border is beautiful.', '2003-06-19 16:31:11.000000', NULL, 1),
(331548, 24905, 5112, '<td valign="top">I love the colours.  Good entry for off center.  I like how the bottom horizon melts into the border.  ~9</td>', 'I love the colours.  Good entry for off center.  I like how the bottom horizon melts into the border.  ~9', '2003-06-19 16:32:07.000000', NULL, 1),
(331553, 24606, 5112, '<td valign="top">Nice picture, beautiful curves.  You captured the jump just right, and I like the shadow.  I wish the face of the girl were a bit clearer.  ~8</td>', 'Nice picture, beautiful curves.  You captured the jump just right, and I like the shadow.  I wish the face of the girl were a bit clearer.  ~8', '2003-06-19 16:33:27.000000', NULL, 1),
(331556, 24949, 5112, '<td valign="top">Ahh, the good ol'' "blue, white, and red" Might this be France? :)  Anyway - good entry.  ~8</td>', 'Ahh, the good ol'' "blue, white, and red" Might this be France? :)  Anyway - good entry.  ~8', '2003-06-19 16:34:24.000000', NULL, 1),
(331563, 24829, 5112, '<td valign="top">Wow, interesting!  Great choice for off-center.  The colours look almost a little overworked, but actually I like them.  The yellow on the sign is great.  I wish you''d included just a little bit more space on the left side of the sign.  ~8</td>', 'Wow, interesting!  Great choice for off-center.  The colours look almost a little overworked, but actually I like them.  The yellow on the sign is great.  I wish you''d included just a little bit more space on the left side of the sign.  ~8', '2003-06-19 16:37:47.000000', NULL, 1),
(331566, 24985, 5112, '<td valign="top">Very nice - I don\''t see much of anything wrong with this picture.  ~9</td>', 'Very nice - I don\''t see much of anything wrong with this picture.  ~9', '2003-06-19 16:38:45.000000', NULL, 1),
(331572, 24634, 5112, '<td valign="top">IMO, this picture would work better if the rose were somehow sharper even though it''s in the fog.  Nice fog by the way.</td>', 'IMO, this picture would work better if the rose were somehow sharper even though it''s in the fog.  Nice fog by the way.', '2003-06-19 16:41:41.000000', NULL, 1),
(331575, 25016, 5112, '<td valign="top">I''m wondering if the movement is intentional?  IMO, this image would work better if it were sharp rather than blurred.  And, even though the man is off-center, the roundish hole is pretty much center, and the two compete for attention.  ~4</td>', 'I''m wondering if the movement is intentional?  IMO, this image would work better if it were sharp rather than blurred.  And, even though the man is off-center, the roundish hole is pretty much center, and the two compete for attention.  ~4', '2003-06-19 16:43:15.000000', NULL, 1),
(331576, 24881, 5112, '<td valign="top">Nice idea, but the snake does not look quite in focus.  The colours of the background IMO take away from the snake.  Also, the triangular shape to the right competes for attention with the snake.  ~4</td>', 'Nice idea, but the snake does not look quite in focus.  The colours of the background IMO take away from the snake.  Also, the triangular shape to the right competes for attention with the snake.  ~4', '2003-06-19 16:43:32.000000', NULL, 1),
(331582, 24861, 5112, '<td valign="top">The clock is off-center, and the picture is clear, but IMO it''s not really a picture that will catch people''s attention.  The door (or window) reflected on the clock is distracting.  Also IMO, the picture might be a bit better if the three small sides (bottom, right, and top) were the same size.  ~4</td>', 'The clock is off-center, and the picture is clear, but IMO it''s not really a picture that will catch people''s attention.  The door (or window) reflected on the clock is distracting.  Also IMO, the picture might be a bit better if the three small sides (bottom, right, and top) were the same size.  ~4', '2003-06-19 16:46:33.000000', NULL, 1),
(331586, 24412, 5112, '<td valign="top">Good idea, but it needs to be in focus and a bit bigger.</td>', 'Good idea, but it needs to be in focus and a bit bigger.', '2003-06-19 16:47:38.000000', NULL, 1),
(331591, 24890, 5112, '<td valign="top">I was hoping heaven was in colour!  Anyway.  Good entry - the sky is very nice, the white of the church walls is beautiful.  ~8</td>', 'I was hoping heaven was in colour!  Anyway.  Good entry - the sky is very nice, the white of the church walls is beautiful.  ~8', '2003-06-19 16:49:24.000000', NULL, 1),
(331592, 24915, 5112, '<td valign="top">Very nice.  I like her bellybutton.  ~8</td>', 'Very nice.  I like her bellybutton.  ~8', '2003-06-19 16:49:52.000000', NULL, 1),
(331597, 24953, 5112, '<td valign="top">Good entry.  IMO, the bee almost gets lost on the flower, and also IMO the sky could be more intense.  I like the white hairs on the flower stem.  ~7</td>', 'Good entry.  IMO, the bee almost gets lost on the flower, and also IMO the sky could be more intense.  I like the white hairs on the flower stem.  ~7', '2003-06-19 16:51:03.000000', NULL, 1),
(331602, 24963, 5112, '<td valign="top">I''m trying to imagine where you were when you took this photo.  You must not be afraid of heights!  It''s a good pict.  It looks like there is almost a bit too much light, and some of the detail on the iceberg and the ship seems lost.  ~7</td>', 'I''m trying to imagine where you were when you took this photo.  You must not be afraid of heights!  It''s a good pict.  It looks like there is almost a bit too much light, and some of the detail on the iceberg and the ship seems lost.  ~7', '2003-06-19 16:53:05.000000', NULL, 1),
(331606, 24657, 5112, '<td valign="top">Her hair is wet, even though she has a beautiful blue umbrella.  I like this picture, but, at least in my opinion, there are too many things in it competing for attention.  ~7</td>', 'Her hair is wet, even though she has a beautiful blue umbrella.  I like this picture, but, at least in my opinion, there are too many things in it competing for attention.  ~7', '2003-06-19 16:56:22.000000', NULL, 1),
(331608, 24984, 5112, '<td valign="top">Very nice.  I love the reflection!  One nitpick:  The lighter blue object in the water at the bottom left corner - it would be nice if it weren''t there.  ~8</td>', 'Very nice.  I love the reflection!  One nitpick:  The lighter blue object in the water at the bottom left corner - it would be nice if it weren''t there.  ~8', '2003-06-19 16:57:43.000000', NULL, 1),
(331610, 24378, 5112, '<td valign="top">Even though the overall shape is off-center, my eyes are drawn to the middle yellow shape, in the center - so I''m having trouble thinking of this photo as "off center".  It also looks a bit out of focus.</td>', 'Even though the overall shape is off-center, my eyes are drawn to the middle yellow shape, in the center - so I''m having trouble thinking of this photo as "off center".  It also looks a bit out of focus.', '2003-06-19 16:59:16.000000', NULL, 1),
(331614, 25010, 5112, '<td valign="top">The photo looks slightly tilted to the right to my eyes, and I''m wondering if it''s oversharpened or if you applied to much contrast improvement.  The light looks a bit harsh.  I like the eyebrows though.</td>', 'The photo looks slightly tilted to the right to my eyes, and I''m wondering if it''s oversharpened or if you applied to much contrast improvement.  The light looks a bit harsh.  I like the eyebrows though.', '2003-06-19 17:01:25.000000', NULL, 1),
(331616, 24643, 5112, '<td valign="top">I\''m wondering if this photo could be improved if the colours were more saturated, or the contrast higher.</td>', 'I\''m wondering if this photo could be improved if the colours were more saturated, or the contrast higher.', '2003-06-19 17:01:51.000000', NULL, 1),
(331623, 24917, 5112, '<td valign="top">The candle is off center, so it meets the challenge.  The green paper is a bit grainy, and the candle is a bit tilted to the right.  Also, there''s something in the top left hand corner that you could have easily cropped out.</td>', 'The candle is off center, so it meets the challenge.  The green paper is a bit grainy, and the candle is a bit tilted to the right.  Also, there''s something in the top left hand corner that you could have easily cropped out.', '2003-06-19 17:04:52.000000', NULL, 1),
(331624, 24792, 5112, '<td valign="top">Nice rust colours (reds)!  IMO, the border really hurst this photo.</td>', 'Nice rust colours (reds)!  IMO, the border really hurst this photo.', '2003-06-19 17:05:57.000000', NULL, 1),
(331626, 24573, 5112, '<td valign="top">Beautiful red pansy!  IMO, the image would be much improved if it were larger, and if you could move away some of the leaves in particular to the left hand side - maybe get a bit closer to the flower (I don''t know if you can with your camera, so excuse my comments if you can''t).</td>', 'Beautiful red pansy!  IMO, the image would be much improved if it were larger, and if you could move away some of the leaves in particular to the left hand side - maybe get a bit closer to the flower (I don''t know if you can with your camera, so excuse my comments if you can''t).', '2003-06-19 17:08:19.000000', NULL, 1),
(331672, 24985, 509, '<td valign="top">Nice work.  I like the effect the focus gives here, though an even more indistinct background would also work.  The image has the effect of anticipation, as if the cars are about to come tearing around the bend. - Mav</td>', 'Nice work.  I like the effect the focus gives here, though an even more indistinct background would also work.  The image has the effect of anticipation, as if the cars are about to come tearing around the bend. - Mav', '2003-06-19 18:12:20.000000', NULL, 1),
(331708, 24672, 9131, '<td valign="top">nice detail, but a litle over-exposed for my taste.  good photo!</td>', 'nice detail, but a litle over-exposed for my taste.  good photo!', '2003-06-19 18:36:51.000000', NULL, 1),
(331711, 24975, 9131, '<td valign="top">very striking composition a lighting! nice!</td>', 'very striking composition a lighting! nice!', '2003-06-19 18:37:26.000000', NULL, 1),
(331719, 24914, 9131, '<td valign="top">when i do off-center subjects (most of the time), i like to place the subject so that it is looking or moving into the bigger space in the photo, instead of the opposite, like you have here.  i do,  however, like the way you have the line of the roof diagonal, but not exactly corner to corner.  nice photo!</td>', 'when i do off-center subjects (most of the time), i like to place the subject so that it is looking or moving into the bigger space in the photo, instead of the opposite, like you have here.  i do,  however, like the way you have the line of the roof diagonal, but not exactly corner to corner.  nice photo!', '2003-06-19 18:43:21.000000', NULL, 1),
(331720, 24771, 9131, '<td valign="top">awesome color, light and detail!</td>', 'awesome color, light and detail!', '2003-06-19 18:44:03.000000', NULL, 1),
(331723, 24829, 9131, '<td valign="top">i like it but it seems a little too color/curves enhanced.</td>', 'i like it but it seems a little too color/curves enhanced.', '2003-06-19 18:45:29.000000', NULL, 1),
(331745, 24792, 9131, '<td valign="top">the green border doesn''t really add to this one...</td>', 'the green border doesn''t really add to this one...', '2003-06-19 19:02:44.000000', NULL, 1),
(331746, 24639, 9131, '<td valign="top">nice macro!!</td>', 'nice macro!!', '2003-06-19 19:03:00.000000', NULL, 1),
(331756, 24798, 9131, '<td valign="top">coming from someone who has learned the hard way: be careful shoointg directly into the sun w/digital.  you can fry the ccd!!! i had it pointed there for several hours, for a time-lapse sequence and ended up with a permanent line through the frame, ouch!  so a brief exposure may be ok.  but keep in mind that with point and shoot, the ccd is being exposed at all times, whereas a dslr''s ccd is blocked by the mirror until the shot is taken.  nice picture, though</td>', 'coming from someone who has learned the hard way: be careful shoointg directly into the sun w/digital.  you can fry the ccd!!! i had it pointed there for several hours, for a time-lapse sequence and ended up with a permanent line through the frame, ouch!  so a brief exposure may be ok.  but keep in mind that with point and shoot, the ccd is being exposed at all times, whereas a dslr''s ccd is blocked by the mirror until the shot is taken.  nice picture, though', '2003-06-19 19:07:27.000000', NULL, 1),
(331896, 25016, 6870, '<td valign="top">NIce mood and leading lines. I sure wish something were in focus, then motion blur would work for me in this somewhat static scene.</td>', 'NIce mood and leading lines. I sure wish something were in focus, then motion blur would work for me in this somewhat static scene.', '2003-06-19 21:07:23.000000', NULL, 1),
