(335100, 24933, 6900, '<td valign="top">I love the feel to this shot - the greens against the red and orange is just fabulous and the whole picture just looks SO moody.  10</td>', 'I love the feel to this shot - the greens against the red and orange is just fabulous and the whole picture just looks SO moody.  10', '2003-06-22 21:39:44.000000', NULL, 1),
